'use strict';
// Lern-Survivor – Algorithmen & Komplexität (LK LB 2, LB 3). Quellen: OPAL LK_INF_LB2_3_-_Programmieren_und_Algorithmen_-_GDP
// (2_algorithmen: 2.2.1–2.2.10), LK_INF_LB2_3_-_Datenstrukturen_und_Komplexitaet_-_GDP (4_berechenbarkeit),
// LK_INF_Abiturvorbereitung_-_GDP 2.2 Suchen, Sortieren und Rekursion, 2.3 Komplexität und Berechenbarkeit,
// Lehrplan Sachsen 2022 LK LB 2 (Problemlösestrategien, Such- und Sortierverfahren) und LB 3 (Komplexität, Berechenbarkeit).
(window.KURS = window.KURS || {}).algo = {
  stufe: 'LK · LB 2/3: Sortieren, O-Notation, Komplexitätsklassen, Divide and Conquer, binäre Suche, Mergesort, Quicksort, Grenzen der Berechenbarkeit',
  fragen: [
    // ---------- 2.2.1 Algorithmen und Komplexität ----------
    {d: 1, t: '2.2.1 Algorithmen und Komplexität', q: 'Was beschreibt die Zeitkomplexität eines Algorithmus?', a: ['wie die Zahl der Rechenschritte mit der Eingabegröße n wächst', 'wie viele Sekunden er auf einem bestimmten Rechner braucht', 'wie viele Zeilen sein Quelltext in Abhängigkeit von n hat', 'wie viel Speicher jede einzelne Variable im Mittel belegt'], e: 'Gezählt werden Schritte in Abhängigkeit von n – unabhängig davon, wie schnell der konkrete Rechner ist.', src: 'OPAL LB2 2.2.1'},
    {d: 1, t: '2.2.1 Algorithmen und Komplexität', q: 'Wie viele Vergleiche braucht man, um unter 8 verdeckten Karten die größte zu finden?', a: ['7', '8', '3', '28'], e: 'Immer n − 1: Jede Karte außer der größten muss mindestens einmal einen Vergleich „verlieren“.', src: 'OPAL LB2 2.2.1'},
    {d: 2, t: '2.2.1 Algorithmen und Komplexität', q: '`hat_doppelte` vergleicht jede Karte mit allen Karten rechts davon. Wie viele Vergleiche sind es bei 10 Karten ohne doppelte?', a: ['45', '100', '90', '10'], e: '9 + 8 + … + 1 + 0 = n · (n − 1) / 2 = 10 · 9 / 2 = 45. Wer das Halbieren vergisst, kommt auf 90.', src: 'OPAL LB2 2.2.1'},
    {d: 2, t: '2.2.1 Algorithmen und Komplexität', q: 'Ein Verfahren braucht etwa n · n / 2 Vergleiche, Python schafft rund 10 Millionen Vergleiche pro Sekunde. Wie lange dauert das Sortieren einer Playlist mit 2 000 Songs?', a: ['etwa 0,2 Sekunden', 'etwa 2,0 Sekunden', 'etwa 20 Sekunden', 'etwa 0,02 Sekunden'], e: '2 000 · 2 000 / 2 = 2 Millionen Vergleiche, geteilt durch 10⁷ pro Sekunde = 0,2 s. Erst bei 100 Millionen Songs wären es rund 16 Jahre.', src: 'OPAL LB2 2.2.1'},

    // ---------- 2.2.2 Bubblesort ----------
    {d: 1, t: '2.2.2 Bubblesort', q: 'Was steht bei Bubblesort nach dem k-ten Durchlauf sicher fest?', a: ['Die k größten Elemente stehen endgültig am Ende der Liste.', 'Die k kleinsten Elemente stehen endgültig am Anfang der Liste.', 'Die ersten k Elemente sind untereinander schon richtig sortiert.', 'Nichts – erst nach dem letzten Durchlauf ist etwas sicher.'], e: 'Große Zahlen steigen wie Luftblasen nach rechts auf. Deshalb wird jeder Durchlauf um einen Vergleich kürzer.', src: 'OPAL LB2 2.2.2'},
    {d: 2, t: '2.2.2 Bubblesort', q: 'Wie sieht die Liste `4, 1, 3, 2` nach dem ersten Durchlauf von Bubblesort aus?', a: ['1, 3, 2, 4', '1, 2, 3, 4', '1, 4, 3, 2', '1, 3, 4, 2'], e: '4/1 tauschen → 1, 4, 3, 2; 4/3 tauschen → 1, 3, 4, 2; 4/2 tauschen → 1, 3, 2, 4. Drei Vertauschungen, die 4 steht am Ende.', src: 'OPAL LB2 2.2.2'},
    {d: 2, t: '2.2.2 Bubblesort', q: 'Wie viele Durchläufe, Vergleiche und Vertauschungen braucht Bubblesort mit Abbruch für `1, 3, 2, 4`?', a: ['2 Durchläufe, 5 Vergleiche, 1 Vertauschung', '1 Durchlauf, 3 Vergleiche, 1 Vertauschung', '3 Durchläufe, 6 Vergleiche, 1 Vertauschung', '2 Durchläufe, 6 Vergleiche, 2 Vertauschungen'], e: 'Durchlauf 1: 3 Vergleiche, 3/2 getauscht. Durchlauf 2: 2 Vergleiche, kein Tausch → Abbruch. Erst ein Durchlauf ohne Tausch zeigt, dass die Liste sortiert ist.', src: 'OPAL LB2 2.2.2'},
    {d: 2, t: '2.2.2 Bubblesort', q: 'Eine Liste hat 20 Elemente. Wie viele Vergleiche braucht Bubblesort im schlechtesten Fall?', a: ['190', '400', '380', '19'], e: '19 + 18 + … + 1 = 20 · 19 / 2 = 190. Im besten Fall (schon sortiert, mit Abbruch) sind es nur 19.', src: 'OPAL LB2 2.2.2'},
    {d: 1, t: '2.2.2 Bubblesort', q: 'Bubblesort mit Abbruch erhält eine bereits sortierte Liste. In welcher Klasse liegt dieser beste Fall?', a: ['O(n)', 'O(n²)', 'O(1)', 'O(n · log n)'], e: 'Ein Durchlauf mit n − 1 Vergleichen ohne Tausch, dann beendet break das Sortieren.', src: 'OPAL LB2 2.2.2'},
    {d: 3, t: '2.2.2 Bubblesort', q: 'Die Liste `5, 2, 9, 3, 4, 6` hat 6 Fehlstellungen. Wie viele Vertauschungen macht Bubblesort?', a: ['6', '15', '12', '4'], e: 'Jede Vertauschung zweier Nachbarn beseitigt genau eine Fehlstellung (ein Paar, das falsch herum steht). 12 ist die Zahl der Vergleiche mit Abbruch.', src: 'OPAL LB2 2.2.2'},

    // ---------- 2.2.3 Einführung in Komplexität und die O-Notation ----------
    {d: 1, t: '2.2.3 Einführung in Komplexität und die O-Notation', q: 'Was bedeutet f(n) ∈ O(g(n))?', a: ['Es gibt c > 0 und n₀ mit f(n) ≤ c · g(n) für alle n ≥ n₀.', 'Es gibt c > 0 und n₀ mit f(n) = c · g(n) für alle n ≥ n₀.', 'Es gibt c > 0 und n₀ mit f(n) ≥ c · g(n) für alle n ≥ n₀.', 'f und g liefern für alle kleinen n genau dieselben Werte.'], e: 'Die O-Notation gibt eine obere Schranke an: Für große n wächst f höchstens so schnell wie g.', src: 'OPAL LB2 2.2.3'},
    {d: 2, t: '2.2.3 Einführung in Komplexität und die O-Notation', q: 'Wie viele Schritte braucht `summe` bei einer Liste mit 6 Zahlen (jede Anweisung 1 Schritt, Schleifenrumpf je Durchlauf)?\n`def summe(liste):\n    s = 0\n    for x in liste:\n        s = s + x\n    return s`', a: ['8', '6', '7', '12'], e: 'f(n) = 1 + n + 1 = n + 2, für n = 6 also 8 Schritte. Das liegt in O(n).', src: 'OPAL LB2 2.2.3'},
    {d: 2, t: '2.2.3 Einführung in Komplexität und die O-Notation', q: 'Welches ist die kleinste passende Komplexitätsklasse für f(n) = 3n² + 5n + 2?', a: ['O(n²)', 'O(n)', 'O(n³)', 'O(log n)'], e: 'Konstante Faktoren und kleinere Terme fallen weg. O(n³) wäre auch eine obere Schranke, aber nicht die kleinste.', src: 'OPAL LB2 2.2.3'},
    {d: 2, t: '2.2.3 Einführung in Komplexität und die O-Notation', q: 'In welcher Klasse liegt dieses Programmstück?\n`for i in range(n):\n    for j in range(5):\n        print(i, j)`', a: ['O(n)', 'O(n²)', 'O(5ⁿ)', 'O(log n)'], e: 'Die innere Schleife läuft immer nur 5-mal: 5 · n Durchläufe. Zwei geschachtelte Schleifen bedeuten nicht automatisch O(n²).', src: 'OPAL LB2 2.2.3'},
    {d: 2, t: '2.2.3 Einführung in Komplexität und die O-Notation', q: 'In welcher Klasse liegt dieses Programmstück?\n`i = n\nwhile i > 1:\n    i = i // 2`', a: ['O(log n)', 'O(n)', 'O(n / 2)', 'O(1)'], e: 'i wird in jedem Durchlauf halbiert. Nach etwa log₂ n Halbierungen ist i bei 1.', src: 'OPAL LB2 2.2.3'},
    {d: 3, t: '2.2.3 Einführung in Komplexität und die O-Notation', q: 'Welche Aussage ist nach der Definition der O-Notation richtig?', a: ['Wenn f ∈ O(n) gilt, dann gilt auch f ∈ O(n²).', 'f(n) = n²/1000 liegt in O(n), weil der Faktor so klein ist.', 'Ein Algorithmus in O(n²) ist immer langsamer als einer in O(n).', '0,2 s für n = 1000 und 0,4 s für n = 2000 zeigen O(n²).'], e: 'O ist eine obere Schranke, n ≤ n² für n ≥ 1. Konstante Faktoren ändern die Klasse nicht, und bei kleinen n kann ein O(n²)-Verfahren schneller sein.', src: 'OPAL LB2 2.2.3'},

    // ---------- 2.2.4 Komplexitätsklassen im Überblick ----------
    {d: 1, t: '2.2.4 Komplexitätsklassen im Überblick', q: 'Welche Reihenfolge der Komplexitätsklassen ist richtig (von langsam zu schnell wachsend)?', a: ['O(1), O(log n), O(n), O(n log n), O(n²), O(2ⁿ), O(n!)', 'O(1), O(n), O(log n), O(n log n), O(n²), O(n!), O(2ⁿ)', 'O(log n), O(1), O(n), O(n²), O(n log n), O(2ⁿ), O(n!)', 'O(1), O(log n), O(n log n), O(n), O(n²), O(2ⁿ), O(n!)'], e: 'O(1) ⊂ O(log n) ⊂ O(n) ⊂ O(n log n) ⊂ O(n²) ⊂ O(2ⁿ) ⊂ O(n!).', src: 'OPAL LB2 2.2.4'},
    {d: 1, t: '2.2.4 Komplexitätsklassen im Überblick', q: 'Bis zu welcher Klasse gelten Algorithmen als effizient?', a: ['bis einschließlich polynomialer Laufzeit O(nᵏ)', 'nur bis zur quadratischen Laufzeit O(n²)', 'bis einschließlich exponentieller Laufzeit O(2ⁿ)', 'nur logarithmische Laufzeit O(log n) oder besser'], e: 'Exponentielle und faktorielle Laufzeiten sind schon für mittlere n praktisch nicht mehr ausführbar.', src: 'OPAL LB2 2.2.4'},
    {d: 1, t: '2.2.4 Komplexitätsklassen im Überblick', q: 'Welche Klasse hat das Problem des Handlungsreisenden mit Brute Force (alle Reihenfolgen der Städte prüfen)?', a: ['O(n!)', 'O(2ⁿ)', 'O(n²)', 'O(n log n)'], e: 'Alle Reihenfolgen von n Städten: faktorieller Aufwand. O(2ⁿ) gehört zum Prüfen aller Teilmengen (Rucksackproblem).', src: 'OPAL LB2 2.2.4'},
    {d: 2, t: '2.2.4 Komplexitätsklassen im Überblick', q: 'Ein Brute-Force-Verfahren prüft alle 2ⁿ Teilmengen und braucht für n = 30 Gegenstände 1 Sekunde. Wie lange etwa für n = 40?', a: ['etwa 17 Minuten', 'etwa 1,3 Sekunden', 'etwa 10 Sekunden', 'etwa 12 Tage'], e: '10 Gegenstände mehr bedeuten · 2¹⁰ = 1024, also etwa 1024 s ≈ 17 min. Bei n = 50 wären es rund 12 Tage.', src: 'OPAL LB2 2.2.4'},
    {d: 3, t: '2.2.4 Komplexitätsklassen im Überblick', q: 'Etwa wie viel Mal mehr Schritte braucht bei n = 1000 ein O(n²)-Verfahren als ein O(n log n)-Verfahren?', a: ['etwa 100-mal', 'etwa 3-mal', 'etwa 10-mal', 'etwa 1000-mal'], e: 'log₂ 1000 ≈ 10 (2¹⁰ ≈ 1000): 1 000 000 : 10 000 = 100. Das Verhältnis n / log n wächst mit n.', src: 'OPAL LB2 2.2.4'},
    {d: 3, t: '2.2.4 Komplexitätsklassen im Überblick', q: 'Ein Rechner wird 1000-mal schneller. Wie groß darf die Eingabe bei einem O(2ⁿ)-Verfahren in derselben Zeit werden?', a: ['nur etwa n + 10 statt n', 'etwa 1000-mal so groß', 'etwa 31-mal so groß', 'etwa doppelt so groß'], e: '2ⁿ⁺¹⁰ = 1024 · 2ⁿ. Bei n² wären es √1000 ≈ 31,6-mal so große Eingaben. Bei exponentiellen Verfahren hilft nur ein besserer Algorithmus.', src: 'OPAL LB2 2.2.4'},

    // ---------- Graphen der Komplexitätsklassen (Wachstumskurven) ----------
    {d: 1, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Im Koordinatensystem (x = n, y = Schritte) verläuft die Kurve eines Algorithmus waagerecht. Welche Klasse ist das?', a: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], e: 'Der Aufwand hängt nicht von n ab, z. B. der Zugriff `liste[i]`. Die Kurve ist eine konstante Funktion.', src: 'OPAL LB2 2.2.4'},
    {d: 1, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Der Graph von f(n) = n ist eine Gerade durch den Ursprung. Welche Klasse ist das, und was passiert beim Verdoppeln von n?', a: ['O(n): Der Aufwand verdoppelt sich.', 'O(n): Der Aufwand vervierfacht sich.', 'O(n²): Der Aufwand verdoppelt sich.', 'O(1): Der Aufwand bleibt gleich.'], e: 'Eine Gerade durch den Ursprung ist linear: doppelt so viele Elemente, doppelt so viele Schritte (lineare Suche).', src: 'OPAL LB2 2.2.4'},
    {d: 1, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Der Graph von f(n) = n² ist eine nach oben geöffnete Parabel. Wie ändert sich f(n), wenn n verdoppelt wird?', a: ['Der Wert vervierfacht sich.', 'Der Wert verdoppelt sich.', 'Der Wert wird um 2 größer.', 'Der Wert wird verachtfacht.'], e: '(2n)² = 4n². Das passt zu den Messwerten von Bubblesort: Verdopplung von n ergibt etwa den Faktor 4.', src: 'OPAL LB2 2.2.3'},
    {d: 1, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Eine Kurve steigt am Anfang steil, wird dann immer flacher und steigt trotzdem unbegrenzt weiter. Welche Klasse passt?', a: ['O(log n)', 'O(1)', 'O(n)', 'O(n²)'], e: 'Jede Verdopplung von n kostet nur einen Schritt mehr (binäre Suche). O(1) wäre waagerecht, O(n) eine Gerade.', src: 'OPAL LB2 2.2.4'},
    {d: 2, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Welche dieser Funktionen wächst für sehr große n am schnellsten?', a: ['2ⁿ', 'n³', 'n² · log₂ n', '1000 · n²'], e: 'Exponentielle Funktionen überholen jedes Polynom, auch mit großem Faktor. Konstante Faktoren ändern die Klasse nicht.', src: 'OPAL LB2 2.2.4'},
    {d: 2, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Welche Wertetabelle stimmt für n = 20?', a: ['n² = 400; 2ⁿ = 1 048 576', 'n² = 400; 2ⁿ = 40', 'n² = 40; 2ⁿ = 1 048 576', 'n² = 400; 2ⁿ ≈ 2,4 · 10¹⁸'], e: '2²⁰ = 1 048 576 (zwanzigmal verdoppelt). 2 · 20 = 40 verwechselt Potenz und Produkt, 2,4 · 10¹⁸ ist 20!.', src: 'OPAL LB2 2.2.4'},
    {d: 3, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Ab welchem n liegt der Graph von 2ⁿ dauerhaft oberhalb des Graphen von n²?', a: ['ab n = 5', 'ab n = 4', 'ab n = 3', 'ab n = 10'], e: 'n = 3: 8 < 9, n = 4: 16 = 16 (gleich), n = 5: 32 > 25, danach wächst der Abstand immer weiter. Bei kleinen n schneiden sich die Kurven also.', src: 'OPAL LB2 2.2.4'},
    {d: 2, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Ein Graph geht durch die Punkte (n = 100; 10 000 Schritte) und (n = 200; 40 000 Schritte). Welche Klasse passt?', a: ['O(n²)', 'O(n)', 'O(n³)', 'O(2ⁿ)'], e: 'Verdopplung von n führt zum Faktor 4: quadratisch. Bei O(n) wären es 20 000, bei O(n³) 80 000 Schritte.', src: 'OPAL LB2 2.2.3'},
    {d: 2, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Wertetabelle: n = 10 → 3 Schritte, n = 100 → 7 Schritte, n = 1000 → 10 Schritte. Welche Klasse zeigt dieser Verlauf?', a: ['O(log n)', 'O(n)', 'O(n log n)', 'O(1)'], e: 'Jede Verzehnfachung von n bringt nur etwa 3,3 Schritte dazu: log₂ 10 ≈ 3,3, log₂ 100 ≈ 6,6, log₂ 1000 ≈ 10.', src: 'OPAL LB2 2.2.4'},
    {d: 3, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Algorithmus A braucht 100 · n Schritte, Algorithmus B braucht n² Schritte. Ab welchem n ist A schneller?', a: ['ab n > 100', 'für jedes n, denn O(n) ist besser als O(n²)', 'ab n > 10', 'für kein n, denn A hat den größeren Faktor'], e: '100 · n = n² gilt bei n = 100. Davor ist B schneller. Die Klasse sagt nur etwas über große n, bei kleinen n zählen die Faktoren.', src: 'OPAL LB2 2.2.3'},
    {d: 2, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Welche Funktion liegt in O(n²)?', a: ['5n² + 100n + 7', 'n³ + n²', '2ⁿ + n', 'n² · log₂ n'], e: 'Es zählt nur der höchste Term, der Faktor 5 fällt weg. Die anderen drei wachsen für große n schneller als n².', src: 'OPAL LB2 2.2.3'},
    {d: 3, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Die Schrittzahl n · log₂ n wird für n = 1024 und n = 2048 berechnet. Wie ändert sie sich?', a: ['≈ 2,2-fach (10 240 → 22 528)', 'genau doppelt (10 240 → 20 480)', 'vierfach (10 240 → 40 960)', 'um 10 Schritte mehr (10 240 → 10 250)'], e: '1024 · 10 = 10 240 und 2048 · 11 = 22 528. Die Kurve liegt etwas steiler als eine Gerade, aber viel flacher als die Parabel.', src: 'OPAL LB2 2.2.4'},
    {d: 2, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Der Aufwand eines Algorithmus verdoppelt sich, wenn n um 1 wächst. Welche Klasse ist das, und wie verläuft die Kurve?', a: ['O(2ⁿ): Sie wird immer steiler.', 'O(n): Sie ist eine Gerade mit Steigung 2.', 'O(n²): Sie ist eine Parabel.', 'O(log n): Sie wird immer flacher.'], e: 'Das ist exponentielles Wachstum: f(n + 1) = 2 · f(n). Zehn Elemente mehr bedeuten etwa das 1000-Fache (2¹⁰ ≈ 1000).', src: 'OPAL LB2 2.2.4'},
    {d: 3, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Messwerte: n = 1000 → 2,0 s; n = 2000 → 4,1 s; n = 4000 → 8,3 s. Welche Klasse passt, und wie lange dauert etwa n = 16 000?', a: ['O(n), etwa 33 s', 'O(n²), etwa 133 s', 'O(n log n), etwa 39 s', 'O(n³), etwa 531 s'], e: 'Jede Verdopplung bringt etwa den Faktor 2, nicht 4 oder 8: linear. Von 4000 auf 16 000 sind es zwei Verdopplungen: 8,3 s · 2 · 2 ≈ 33 s. Quadratisch wären es 133 s.', src: 'OPAL LB2 2.2.4'},

    {d: 1, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Welche Komplexitätsklasse zeigt dieser Graph (x = Eingabegröße n, y = Schritte)?', alt: 'Koordinatensystem mit einer waagerechten Geraden bei y = 5', plot: {x: [0, 10], y: [0, 10], xl: 'n', yl: 'Schritte', curves: [{f: function(n) { return 5; }}]}, a: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], e: 'Der Aufwand bleibt bei jedem n gleich: Die Kurve ist waagerecht, also konstant (z. B. der Zugriff liste[i]).', src: 'OPAL LB2 2.2.4'},
    {d: 1, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Welche Komplexitätsklasse zeigt dieser Graph (x = Eingabegröße n, y = Schritte)?', alt: 'Koordinatensystem mit einer Geraden durch den Ursprung', plot: {x: [0, 10], y: [0, 10], xl: 'n', yl: 'Schritte', curves: [{f: function(n) { return n; }}]}, a: ['O(n)', 'O(1)', 'O(n²)', 'O(log n)'], e: 'Eine Gerade durch den Ursprung ist linear: doppelt so viele Elemente, doppelt so viele Schritte (z. B. lineare Suche).', src: 'OPAL LB2 2.2.4'},
    {d: 2, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Welche Komplexitätsklasse zeigt dieser Graph (x = Eingabegröße n, y = Schritte)?', alt: 'Koordinatensystem mit einer nach oben geöffneten Parabel, die flach beginnt und immer steiler wird', plot: {x: [0, 10], y: [0, 10], xl: 'n', yl: 'Schritte', curves: [{f: function(n) { return n * n / 10; }}]}, a: ['O(n²)', 'O(n)', 'O(log n)', 'O(1)'], e: 'Die Kurve beginnt flach und wird immer steiler: eine Parabel. Bei doppeltem n ist der Wert viermal so groß (n = 5: 2,5; n = 10: 10).', src: 'OPAL LB2 2.2.4'},
    {d: 1, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Welche Komplexitätsklasse zeigt dieser Graph (x = Eingabegröße n, y = Schritte)?', alt: 'Koordinatensystem mit einer Kurve, die anfangs steil steigt und dann immer flacher wird', plot: {x: [1, 64], y: [0, 8], xt: [1, 16, 32, 48, 64], yt: [0, 2, 4, 6, 8], xl: 'n', yl: 'Schritte', curves: [{f: function(n) { return Math.log(n) / Math.log(2); }}]}, a: ['O(log n)', 'O(n)', 'O(n²)', 'O(1)'], e: 'Die Kurve steigt zuerst steil und wird dann immer flacher, steigt aber ohne Grenze weiter. Jede Verdopplung von n bringt nur einen Schritt dazu (z. B. binäre Suche).', src: 'OPAL LB2 2.2.4'},
    {d: 2, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Welche Komplexitätsklasse zeigt dieser Graph (x = Eingabegröße n, y = Schritte)?', alt: 'Koordinatensystem mit einer Kurve, die lange fast waagerecht bleibt und dann senkrecht nach oben schießt', plot: {x: [0, 20], y: [0, 1000000], xt: [0, 5, 10, 15, 20], yt: [0, 250000, 500000, 750000, 1000000], xl: 'n', yl: 'Schritte', curves: [{f: function(n) { return Math.pow(2, n); }}]}, a: ['O(2ⁿ)', 'O(n²)', 'O(n log n)', 'O(n)'], e: 'Der Graph bleibt lange fast flach und schießt dann steil nach oben: Jedes zusätzliche n verdoppelt die Schrittzahl (2²⁰ = 1 048 576). Eine Parabel steigt viel gleichmäßiger.', src: 'OPAL LB2 2.2.4'},
    {d: 3, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Der Graph zeigt die Schritte für n² (Kurve A) und 2ⁿ (Kurve B). Welche Aussage stimmt?', alt: 'Koordinatensystem von n = 0 bis 8 mit zwei Kurven: A ist die Parabel n², B die Exponentialkurve 2ⁿ; sie schneiden sich bei n = 2 und n = 4, danach liegt B oben', plot: {x: [0, 8], y: [0, 100], xt: [0, 1, 2, 3, 4, 5, 6, 7, 8], yt: [0, 25, 50, 75, 100], xl: 'n', yl: 'Schritte', curves: [{f: function(n) { return n * n; }, label: 'A', color: '#38bdf8'}, {f: function(n) { return Math.pow(2, n); }, label: 'B', color: '#fde047'}]}, a: ['Ab n = 5 liegt 2ⁿ (Kurve B) dauerhaft über n² (Kurve A).', 'Ab n = 3 liegt 2ⁿ (Kurve B) dauerhaft über n² (Kurve A).', 'Ab n = 5 liegt n² (Kurve A) dauerhaft über 2ⁿ (Kurve B).', 'Die Kurven schneiden sich nie, 2ⁿ liegt immer über n².'], e: 'Bei n = 2 und n = 4 schneiden sich die Kurven (4 = 4, 16 = 16), dazwischen liegt n² darüber (n = 3: 9 > 8). Ab n = 5 ist 2ⁿ größer (32 > 25) und zieht immer weiter davon.', src: 'OPAL LB2 2.2.4'},
    {d: 3, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Algorithmus A braucht 100 · n Schritte (Gerade), Algorithmus B braucht n² Schritte (Parabel). Ab welchem n ist A schneller?', alt: 'Koordinatensystem von n = 0 bis 200: eine Gerade A und eine Parabel B schneiden sich bei n = 100 und 10 000 Schritten', plot: {x: [0, 200], y: [0, 20000], xt: [0, 50, 100, 150, 200], yt: [0, 5000, 10000, 15000, 20000], xl: 'n', yl: 'Schritte', curves: [{f: function(n) { return 100 * n; }, label: 'A', color: '#38bdf8'}, {f: function(n) { return n * n; }, label: 'B', color: '#fde047'}]}, a: ['ab etwa n = 100', 'ab etwa n = 50', 'ab etwa n = 150', 'schon ab n = 1'], e: 'Die Kurven schneiden sich bei n = 100 (beide 10 000 Schritte). Danach liegt die Parabel B darüber, A braucht weniger. Davor ist B kleiner: Bei kleinen n zählen die Faktoren, die Klasse sagt nur etwas über große n.', src: 'OPAL LB2 2.2.3'},
    {d: 3, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Die drei Kurven gehören zu n, n · log₂ n und n². Welche Kurve gehört zu n · log₂ n?', alt: 'Koordinatensystem von n = 0 bis 64 mit drei Kurven: A steigt am steilsten und verlässt bei etwa n = 20 das Bild, B liegt bei n = 64 etwa bei 384, C ist eine Gerade durch (64, 64)', plot: {x: [0, 64], y: [0, 400], xt: [0, 16, 32, 48, 64], yt: [0, 100, 200, 300, 400], xl: 'n', yl: 'Schritte', curves: [{f: function(n) { return n * n; }, label: 'A', color: '#f87171'}, {f: function(n) { return n < 1 ? 0 : n * Math.log(n) / Math.log(2); }, label: 'B', color: '#fde047'}, {f: function(n) { return n; }, label: 'C', color: '#38bdf8'}]}, a: ['Kurve B, denn sie liegt zwischen der Geraden und der Parabel.', 'Kurve A, denn sie steigt am steilsten und verlässt zuerst das Bild.', 'Kurve C, denn sie ist die gerade Linie durch den Ursprung.', 'Keine, denn n · log₂ n lässt sich nicht als Kurve darstellen.'], e: 'n · log₂ n wächst schneller als die Gerade n, aber deutlich langsamer als die Parabel n². Bei n = 64: 64 · 6 = 384 gegenüber 64 und 4096. A ist n², C ist n.', src: 'OPAL LB2 2.2.4'},
    {d: 2, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Die Punkte zeigen gemessene Laufzeiten in Sekunden bei verschiedener Eingabegröße n. Welche Klasse passt?', alt: 'Koordinatensystem mit drei Messpunkten bei n = 1000 (2,0 s), n = 2000 (4,1 s) und n = 4000 (8,3 s), sie liegen auf einer Geraden durch den Ursprung', plot: {x: [0, 5000], y: [0, 10], xt: [0, 1000, 2000, 3000, 4000, 5000], yt: [0, 2, 4, 6, 8, 10], xl: 'n', yl: 'Sekunden', points: [{x: 1000, y: 2}, {x: 2000, y: 4.1}, {x: 4000, y: 8.3}]}, a: ['O(n)', 'O(n²)', 'O(log n)', 'O(2ⁿ)'], e: 'Die Punkte liegen auf einer Geraden durch den Ursprung: doppeltes n, doppelte Zeit (2,0 → 4,1 → 8,3 s). Bei O(n²) wären es 2 → 8 → 32 s.', src: 'OPAL LB2 2.2.3'},
    {d: 1, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Welcher Graph gehört zu einem Algorithmus der Klasse O(n²)?', a: [{alt: 'Parabel', plot: {mini: true, x: [0, 10], y: [0, 10], curves: [{f: function(n) { return n * n / 10; }}]}}, {alt: 'Gerade', plot: {mini: true, x: [0, 10], y: [0, 10], curves: [{f: function(n) { return n; }}]}}, {alt: 'flacher werdende Kurve', plot: {mini: true, x: [0, 10], y: [0, 10], curves: [{f: function(n) { return 2.9 * Math.log(n + 1) / Math.log(2); }}]}}, {alt: 'waagerechte Linie', plot: {mini: true, x: [0, 10], y: [0, 10], curves: [{f: function(n) { return 5; }}]}}], e: 'O(n²) ergibt eine Parabel: Sie startet flach und wird immer steiler. Die Gerade gehört zu O(n), die flacher werdende Kurve zu O(log n), die waagerechte Linie zu O(1).', src: 'OPAL LB2 2.2.4'},
    {d: 2, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Welcher Graph zeigt exponentielles Wachstum, also die Klasse O(2ⁿ)?', a: [{alt: 'Exponentialkurve', plot: {mini: true, x: [0, 10], y: [0, 100], curves: [{f: function(n) { return Math.pow(2, n); }}]}}, {alt: 'Parabel', plot: {mini: true, x: [0, 10], y: [0, 100], curves: [{f: function(n) { return n * n; }}]}}, {alt: 'Gerade', plot: {mini: true, x: [0, 10], y: [0, 100], curves: [{f: function(n) { return 10 * n; }}]}}, {alt: 'flacher werdende Kurve', plot: {mini: true, x: [0, 10], y: [0, 100], curves: [{f: function(n) { return 29 * Math.log(n + 1) / Math.log(2); }}]}}], e: 'Der Graph bleibt kurz flach und schießt dann fast senkrecht nach oben: Jedes zusätzliche n verdoppelt den Wert. Die Parabel (n²) steigt deutlich gemächlicher, die Gerade (n) gleichmäßig.', src: 'OPAL LB2 2.2.4'},
    {d: 2, t: 'Graphen der Komplexitätsklassen (Wachstumskurven)', q: 'Der Graph zeigt die Schritte der binären Suche in einer sortierten Liste mit n Einträgen. Wie viele Schritte sind es bei n = 64 etwa?', alt: 'Koordinatensystem von n = 1 bis 64: eine flacher werdende Kurve, die bei n = 64 den Wert 6 erreicht', plot: {x: [1, 64], y: [0, 8], xt: [1, 16, 32, 48, 64], yt: [0, 2, 4, 6, 8], xl: 'n', yl: 'Schritte', curves: [{f: function(n) { return Math.log(n) / Math.log(2); }}]}, a: ['etwa 6', 'etwa 32', 'etwa 64', 'etwa 8'], e: 'Bei n = 64 liest man etwa y = 6 ab: log₂ 64 = 6. Der Aufwand wächst nur logarithmisch, 64 Einträge brauchen also nicht 64 Schritte.', src: 'OPAL LB2 2.2.8'},
    // ---------- Komplexitätsklasse aus dem Code bestimmen ----------
    {d: 1, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'In welcher Klasse liegt der Zugriff `wert = liste[5000]` auf eine Liste mit n Elementen?', a: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], e: 'Der Zugriff über den Index dauert immer gleich lang, egal wie lang die Liste ist.', src: 'OPAL LB2 2.2.4'},
    {d: 1, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'Welche Klasse hat die Abfrage `if gesucht in liste:` im schlechtesten Fall bei einer Liste mit n Elementen?', a: ['O(n)', 'O(1)', 'O(log n)', 'O(n²)'], e: '`in` durchsucht die Liste von vorn Element für Element (lineare Suche). O(log n) gilt nur für die binäre Suche in einer sortierten Liste.', src: 'OPAL LB2 2.2.4'},
    {d: 1, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'Wie oft wird `zaehler` erhöht, und welche Klasse hat das Programmstück?\n`for i in range(n):\n    for j in range(n):\n        zaehler = zaehler + 1`', a: ['n · n Mal; O(n²)', 'n + n Mal; O(n)', 'n Mal; O(n)', '2ⁿ Mal; O(2ⁿ)'], e: 'Die innere Schleife läuft bei jedem der n Durchläufe der äußeren Schleife n-mal: n · n = n² Durchläufe.', src: 'OPAL LB2 2.2.3'},
    {d: 1, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'Pythons `liste.sort()` nutzt ein effizientes Verfahren (ähnlich Mergesort). Welche Klasse hat das Sortieren von n Elementen?', a: ['O(n log n)', 'O(n)', 'O(n²)', 'O(log n)'], e: 'Effiziente Vergleichsverfahren wie Mergesort liegen in O(n log n). Bubblesort, Insertionsort und Selectionsort sind dagegen O(n²).', src: 'OPAL LB2 2.2.4'},
    {d: 2, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'Wie viele Ausgaben macht das Programmstück, und welche Klasse hat es?\n`for i in range(n):\n    print(i)\nfor j in range(n):\n    print(j)`', a: ['2n Ausgaben; O(n)', 'n · n Ausgaben; O(n²)', 'n Ausgaben; O(n)', '2n Ausgaben; O(n²)'], e: 'Zwei Schleifen hintereinander addieren sich: n + n = 2n. Der Faktor 2 fällt weg, also O(n). Multipliziert wird nur bei Schleifen in Schleifen.', src: 'OPAL LB2 2.2.3'},
    {d: 2, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'Welchen Wert hat `zaehler` am Ende für n = 4, und welche Klasse hat die Laufzeit?\n`zaehler = 0\nfor i in range(n):\n    for j in range(i, n):\n        zaehler = zaehler + 1`', a: ['10; O(n²)', '16; O(n²)', '10; O(n)', '6; O(n²)'], e: 'Die innere Schleife läuft 4 + 3 + 2 + 1 = 10-mal, allgemein n · (n + 1) / 2 – das liegt in O(n²). 16 wäre die volle Doppelschleife.', src: 'OPAL Abi 2.3'},
    {d: 2, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'Wie oft läuft die Schleife für n = 1000 etwa, und welche Klasse hat sie?\n`k = 1\nwhile k < n:\n    k = k * 2`', a: ['10-mal; O(log n)', '1000-mal; O(n)', '500-mal; O(n)', '100-mal; O(n)'], e: 'k wird verdoppelt: 1, 2, 4, …, 1024 – das sind 10 Verdopplungen (2¹⁰ ≈ 1000). Verdoppeln und Halbieren führen beide zu O(log n).', src: 'OPAL Abi 2.3'},
    {d: 2, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'Wie viele Aufrufe macht `fakultaet(6)` (einschließlich des ersten), und welche Klasse hat die Laufzeit in n?\n`def fakultaet(n):\n    if n <= 1:\n        return 1\n    return n * fakultaet(n - 1)`', a: ['6 Aufrufe; O(n)', '720 Aufrufe; O(n!)', '6 Aufrufe; O(n!)', '6 Aufrufe; O(n²)'], e: 'Es gibt die Aufrufe für 6, 5, 4, 3, 2, 1: genau n Aufrufe, jeder mit konstanter Arbeit – also O(n). Das Ergebnis ist n!, der Aufwand nicht.', src: 'OPAL LB2 2.2.7'},
    {d: 3, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'In welcher Klasse liegt die Zahl der Aufrufe von `fib(n)`?\n`def fib(n):\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)`', a: ['O(2ⁿ)', 'O(n)', 'O(n²)', 'O(n!)'], e: 'Jeder Aufruf mit n ≥ 2 erzeugt zwei neue Aufrufe, der Aufrufbaum hat Tiefe n. Dieselben Teilprobleme werden mehrfach berechnet. Nur die Tiefe ist n.', src: 'OPAL LB2 2.2.4'},
    {d: 2, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'Wie oft läuft die while-Schleife bei einer sortierten Liste mit 1000 Elementen im schlechtesten Fall etwa?\n`def binaere_suche(liste, gesucht):\n    links = 0\n    rechts = len(liste) - 1\n    while links <= rechts:\n        mitte = (links + rechts) // 2\n        if liste[mitte] == gesucht:\n            return mitte\n        elif gesucht < liste[mitte]:\n            rechts = mitte - 1\n        else:\n            links = mitte + 1\n    return -1`', a: ['etwa 10-mal', 'etwa 1000-mal', 'etwa 500-mal', 'etwa 100-mal'], e: 'Der Suchbereich wird in jedem Durchlauf halbiert: log₂ 1000 ≈ 10 (2¹⁰ ≈ 1000). Das ist O(log n).', src: 'OPAL LB2 2.2.8'},
    {d: 2, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'Wie viele Vergleiche `liste[i] == gesucht` braucht die Funktion bei 100 Elementen im best case und im worst case?\n`def lineare_suche(liste, gesucht):\n    for i in range(len(liste)):\n        if liste[i] == gesucht:\n            return i\n    return -1`', a: ['1 und 100', '0 und 99', '1 und 50', '100 und 100'], e: 'Best case: Das Gesuchte steht an erster Stelle. Worst case: Es steht ganz hinten oder fehlt, dann werden alle 100 Elemente verglichen.', src: 'OPAL Abi 2.3'},
    {d: 3, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'Der gesuchte Wert kommt in der Liste genau einmal vor, alle Positionen sind gleich wahrscheinlich. Wie viele Vergleiche braucht `lineare_suche` bei n = 100 im Mittel, und welche Klasse hat der average case?', a: ['etwa 50; O(n)', 'etwa 50; O(n/2), also besser als O(n)', 'etwa 7; O(log n)', 'genau 1; O(1)'], e: 'Im Mittel wird etwa die Hälfte der Liste durchsucht (50,5). Der Faktor ½ fällt weg: Der average case liegt wie der worst case in O(n).', src: 'OPAL Abi 2.3'},
    {d: 3, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'Wie viele Additionen macht das Programmstück insgesamt, und welche Klasse hat es?\n`for i in range(n):\n    for j in range(n):\n        a = a + 1\nfor k in range(n):\n    b = b + 1`', a: ['n² + n Additionen; O(n²)', 'n² + n Additionen; O(n)', 'n² · n Additionen; O(n³)', '2n Additionen; O(n)'], e: 'Die Doppelschleife kostet n², die einzelne Schleife danach n. Der größere Term bestimmt die Klasse: n² + n ∈ O(n²).', src: 'OPAL LB2 2.2.3'},
    {d: 3, t: 'Komplexitätsklasse aus dem Code bestimmen', q: 'Welche Klasse hat dieses Programmstück?\n`for i in range(n):\n    k = 1\n    while k < n:\n        k = k * 2`', a: ['O(n · log n)', 'O(n²)', 'O(n)', 'O(log n)'], e: 'Die innere while-Schleife läuft etwa log₂ n-mal (Verdoppeln), und das für jedes der n Durchläufe der for-Schleife: n · log n.', src: 'OPAL Abi 2.3'},

    // ---------- 2.2.5 Insertionsort und Selectionsort ----------
    {d: 1, t: '2.2.5 Insertionsort und Selectionsort', q: 'Wie arbeitet Insertionsort?', a: ['Das erste Element des unsortierten Teils wird an der richtigen Stelle in den sortierten Teil eingefügt.', 'Das kleinste Element des unsortierten Teils wird gesucht und mit dem ersten Element des unsortierten Teils vertauscht.', 'Benachbarte Elemente werden verglichen und getauscht, bis ein Durchlauf ohne Tausch bleibt.', 'Die Liste wird halbiert, beide Hälften werden sortiert und zusammengeführt.'], e: 'Wie Spielkarten auf der Hand: Jede neue Karte wird an die passende Stelle gesteckt.', src: 'OPAL LB2 2.2.5'},
    {d: 1, t: '2.2.5 Insertionsort und Selectionsort', q: 'Welches der Verfahren ist nicht stabil?', a: ['Selectionsort', 'Insertionsort', 'Bubblesort', 'Mergesort mit <= in merge'], e: 'Stabil heißt: Gleiche Schlüssel behalten ihre Reihenfolge. Der weite Tausch von Selectionsort kann gleiche Elemente überspringen.', src: 'OPAL LB2 2.2.5'},
    {d: 2, t: '2.2.5 Insertionsort und Selectionsort', q: 'In `2, 6, 8, 9, 5, 1` sind die ersten vier Zahlen sortiert. Wie viele Vergleiche braucht Insertionsort zum Einfügen der 5?', a: ['4', '3', '5', '1'], e: '9 > 5, 8 > 5, 6 > 5 (je tauschen), 2 > 5? Nein → Stopp. 4 Vergleiche, 3 Vertauschungen: 2, 5, 6, 8, 9, 1.', src: 'OPAL LB2 2.2.5'},
    {d: 2, t: '2.2.5 Insertionsort und Selectionsort', q: 'Sortiere `7, 3, 5, 1` mit Selectionsort (Tausch nur, wenn `min_pos != i`). Wie viele Vertauschungen und Vergleiche?', a: ['1 Vertauschung, 6 Vergleiche', '3 Vertauschungen, 6 Vergleiche', '1 Vertauschung, 3 Vergleiche', '2 Vertauschungen, 5 Vergleiche'], e: 'Nur die 1 wird mit der 7 getauscht (1, 3, 5, 7); danach steht das Minimum schon vorn. Verglichen wird trotzdem 3 + 2 + 1 = 6-mal.', src: 'OPAL LB2 2.2.5'},
    {d: 2, t: '2.2.5 Insertionsort und Selectionsort', q: 'Welches Verfahren braucht auch für eine bereits sortierte Liste n · (n − 1) / 2 Vergleiche?', a: ['Selectionsort', 'Insertionsort', 'Bubblesort mit Abbruch', 'keines der drei'], e: 'Selectionsort sucht in jedem Schritt das Minimum im ganzen Rest. Insertionsort und Bubblesort mit Abbruch kommen mit n − 1 Vergleichen aus.', src: 'OPAL LB2 2.2.5'},
    {d: 3, t: '2.2.5 Insertionsort und Selectionsort', q: 'Mit einem stabilen Verfahren soll nach Nachname und bei gleichem Nachnamen nach Vorname sortiert werden. Wie geht man vor?', a: ['erst nach Vorname sortieren, danach nach Nachname', 'erst nach Nachname sortieren, danach nach Vorname', 'nur nach Nachname sortieren, die Vornamen ordnen sich von selbst', 'beide Läufe mit Selectionsort durchführen'], e: 'Zuerst das unwichtigere Merkmal, dann das wichtigere. Der zweite, stabile Lauf erhält bei gleichem Nachnamen die Vornamen-Reihenfolge.', src: 'OPAL LB2 2.2.5'},
    {d: 3, t: '2.2.5 Insertionsort und Selectionsort', q: 'Jeder Schreibvorgang auf dem Speicher ist teuer und nutzt ihn ab. Welches einfache Verfahren passt am besten?', a: ['Selectionsort – höchstens n − 1 Vertauschungen', 'Bubblesort – tauscht nur direkte Nachbarn miteinander', 'Insertionsort – ist stabil und im besten Fall linear', 'Alle drei gleich, denn alle liegen in der Klasse O(n²).'], e: 'Selectionsort vergleicht zwar immer n · (n − 1) / 2-mal, schreibt aber am wenigsten. Bubblesort und Insertionsort tauschen bis zu n · (n − 1) / 2-mal.', src: 'OPAL LB2 2.2.5'},

    // ---------- 2.2.6 Darstellung von Algorithmen ----------
    {d: 1, t: '2.2.6 Darstellung von Algorithmen', q: 'Welche genormte Darstellung zeigt einen Algorithmus als ineinander geschachtelte Blöcke, in denen keine Sprünge möglich sind?', a: ['Struktogramm (Nassi-Shneiderman-Diagramm)', 'Programmablaufplan (Flussdiagramm, PAP)', 'Pseudocode (informelle Textbeschreibung)', 'Aufrufbaum (Darstellung der Rekursion)'], e: 'Der PAP (Flussdiagramm) verbindet Symbole mit Pfeilen und erlaubt deshalb auch unstrukturierte Sprünge.', src: 'OPAL LB2 2.2.6'},
    {d: 1, t: '2.2.6 Darstellung von Algorithmen', q: 'Welches Symbol steht im Programmablaufplan für eine Verzweigung?', a: ['Raute', 'Rechteck', 'abgerundetes Rechteck', 'Kreis'], e: 'Rechteck = Anweisung, Raute = Verzweigung, abgerundetes Rechteck = Start/Ende.', src: 'OPAL LB2 2.2.6'},
    {d: 2, t: '2.2.6 Darstellung von Algorithmen', q: 'Was gibt der Algorithmus für n = 13 aus? (div = ganzzahlige Division, mod = Rest)\n`z ← 0\nsolange n > 0:\n    wenn n mod 2 = 1: z ← z + 1\n    n ← n div 2\nAusgabe: z`', a: ['3', '4', '6', '1'], e: 'n: 13 → 6 → 3 → 1 → 0, ungerade waren 13, 3 und 1. Der Algorithmus zählt die Einsen der Binärzahl 1101.', src: 'OPAL LB2 2.2.6'},

    // ---------- 2.2.8 Divide and Conquer, binäre Suche ----------
    {d: 1, t: '2.2.8 Divide and Conquer, binäre Suche', q: 'Aus welchen drei Schritten besteht Divide and Conquer?', a: ['Teilen, Herrschen, Kombinieren', 'Prüfen, Setzen, Zurücknehmen', 'Eingabe, Verarbeitung, Ausgabe', 'Suchen, Tauschen, Ausgeben'], e: 'Problem in kleinere gleichartige Teilprobleme zerlegen, diese (meist rekursiv) lösen, Teillösungen kombinieren. Prüfen – Setzen – Zurücknehmen ist Backtracking.', src: 'OPAL LB2 2.2.8'},
    {d: 1, t: '2.2.8 Divide and Conquer, binäre Suche', q: 'Was setzt die binäre Suche voraus?', a: ['eine sortierte Liste', 'eine Liste mit gerader Länge', 'eine Liste ohne doppelte Werte', 'eine Liste aus ganzen Zahlen'], e: 'Nur in einer sortierten Liste darf nach einem Vergleich eine Hälfte wegfallen.', src: 'OPAL LB2 2.2.8'},
    {d: 2, t: '2.2.8 Divide and Conquer, binäre Suche', q: 'Binäre Suche nach 74 in `48, 51, 53, 57, 60, 62, 64, 67, 69, 71, 74, 78, 80, 85, 91` (Index 0 bis 14, mitte = (links + rechts) // 2). Welche Werte stehen nacheinander an der Stelle mitte?', a: ['67, 78, 71, 74', '67, 80, 74, 71', '64, 78, 74, 67', '67, 71, 78, 74'], e: '(0, 14) → mitte 7: 67; (8, 14) → 11: 78; (8, 10) → 9: 71; (10, 10) → 10: 74 gefunden nach 4 Runden.', src: 'OPAL Abi 2.2'},
    {d: 2, t: '2.2.8 Divide and Conquer, binäre Suche', q: 'Wie viele Vergleichsrunden braucht die binäre Suche höchstens bei 1 000 000 sortierten Einträgen?', a: ['20', '1 000 000', '500 000', '1000'], e: '⌊log₂ n⌋ + 1 = 19 + 1 = 20, denn 2²⁰ ≈ 1 000 000. Die lineare Suche braucht im schlechtesten Fall 1 000 000 Vergleiche.', src: 'OPAL LB2 2.2.8'},
    {d: 3, t: '2.2.8 Divide and Conquer, binäre Suche', q: 'Was liefert die binäre Suche (aus dem Kurs) für `binaere_suche([5, 1, 9], 5)`?', a: ['-1, obwohl 5 vorkommt', '0, weil 5 an Index 0 steht', '1, weil 5 größer als 1 ist', 'IndexError beim zweiten Vergleich'], e: 'mitte = 1: liste[1] = 1, 5 > 1 → rechts weiter. mitte = 2: 9, 5 < 9 → links > rechts → −1. Die Vorbedingung „sortiert“ ist verletzt.', src: 'OPAL LB2 2.2.8'},

    // ---------- 2.2.9 Mergesort ----------
    {d: 1, t: '2.2.9 Mergesort', q: 'In welcher Klasse liegt Mergesort?', a: ['immer O(n · log n), auch im schlechtesten Fall', 'im schlechtesten Fall O(n²), im Mittel O(n · log n)', 'im besten Fall O(n), wenn die Liste schon sortiert ist', 'immer O(log n), weil die Liste ständig halbiert wird'], e: 'Es entstehen etwa log₂ n Ebenen, auf jeder werden beim Zusammenführen höchstens n Elemente bewegt.', src: 'OPAL LB2 2.2.9'},
    {d: 1, t: '2.2.9 Mergesort', q: 'Welchen Nachteil hat Mergesort?', a: ['Er braucht zusätzlichen Speicher für Teillisten (O(n)).', 'Er ist nicht stabil, gleiche Werte werden vertauscht.', 'Im schlechtesten Fall braucht er quadratisch viele Vergleiche.', 'Er kann nur Zahlen sortieren, keine Texte oder Tupel.'], e: 'Mit den Karten: Für Mergesort braucht man eine zweite Reihe auf dem Tisch.', src: 'OPAL LB2 2.2.9'},
    {d: 2, t: '2.2.9 Mergesort', q: 'Wie viele Vergleiche braucht das Zusammenführen (merge) von `[1, 6]` und `[2, 3, 9]`?', a: ['4', '5', '3', '6'], e: '1 ≤ 2 → 1; 6 ≤ 2 nein → 2; 6 ≤ 3 nein → 3; 6 ≤ 9 → 6. Jetzt ist links leer, die 9 kommt ohne Vergleich dazu.', src: 'OPAL LB2 2.2.9'},
    {d: 2, t: '2.2.9 Mergesort', q: 'Wie viele Vergleiche braucht `merge([5, 12, 20], [3, 8, 25, 30])`?', a: ['5', '6', '7', '3'], e: '5/3 → 3; 5/8 → 5; 12/8 → 8; 12/25 → 12; 20/25 → 20. Links ist leer, 25 und 30 kommen ohne Vergleich dazu. a + b − 1 = 6 ist nur die Höchstzahl.', src: 'OPAL Abi 2.2'},
    {d: 3, t: '2.2.9 Mergesort', q: 'Nach `zahlen = [3, 1, 2]` wird `mergesort(zahlen)` aufgerufen. Was steht danach in zahlen?', a: ['[3, 1, 2]', '[1, 2, 3]', 'None', '[]'], e: 'mergesort arbeitet mit Kopien (liste[:mitte]) und gibt eine neue Liste zurück. Richtig: zahlen = mergesort(zahlen).', src: 'OPAL LB2 2.2.9'},
    {d: 3, t: '2.2.9 Mergesort', q: 'Warum steht in merge `links[i] <= rechts[j]` und nicht `<`?', a: ['Bei Gleichstand kommt das linke Element zuerst, so bleibt Mergesort stabil.', 'Mit < würden Elemente verloren gehen, weil Gleiche übersprungen werden.', 'Mit < entstünde eine Endlosschleife, sobald zwei Werte gleich sind.', 'Mit <= werden bei Gleichstand weniger Vergleiche gebraucht als mit <.'], e: 'Das linke Element stand ursprünglich weiter vorn. Mit < würden gleiche Werte vertauscht.', src: 'OPAL LB2 2.2.9'},

    // ---------- 2.2.9b Quicksort ----------
    {d: 1, t: '2.2.9b Quicksort', q: 'Was ist bei Quicksort das Pivot?', a: ['das Element, nach dem in kleinere und größere aufgeteilt wird', 'das kleinste Element der Liste, das zuerst nach vorn getauscht wird', 'die Mitte, an der die Liste ohne Vergleich halbiert wird', 'ein Zähler, der die Vergleiche beim Aufteilen mitzählt'], e: 'Nach dem Aufteilen steht das Pivot an seinem endgültigen Platz.', src: 'OPAL LB2 2.2.9b'},
    {d: 1, t: '2.2.9b Quicksort', q: 'Wie wählt man das Pivot in der Praxis, damit der schlechteste Fall unwahrscheinlich wird?', a: ['ein mittleres oder zufälliges Element oder der Median aus drei', 'immer das erste Element, weil es am schnellsten zu finden ist', 'immer das letzte Element, weil dort die Liste endet', 'immer das kleinste Element, damit ein Teil sofort leer ist'], e: 'Ganz ausschließen lässt sich der schlechteste Fall nicht, aber er wird extrem unwahrscheinlich.', src: 'OPAL LB2 2.2.9b'},
    {d: 2, t: '2.2.9b Quicksort', q: 'Teile `[6, 3, 9, 1, 8, 4]` mit dem Pivot 4 (der letzten Zahl) auf. Was steht in `kleiner`?', a: ['[3, 1]', '[1, 3]', '[3, 1, 4]', '[6, 9, 8]'], e: 'Die Reihenfolge bleibt beim Aufteilen erhalten. gleich = [4], groesser = [6, 9, 8]. Die 4 steht damit schon auf Platz 2.', src: 'OPAL LB2 2.2.9b'},
    {d: 2, t: '2.2.9b Quicksort', q: 'Quicksort mit der letzten Zahl als Pivot erhält eine bereits sortierte Liste. Welche Laufzeit ergibt sich?', a: ['O(n²)', 'O(n · log n)', 'O(n)', 'O(log n)'], e: 'Das Pivot ist immer das größte Element, groesser bleibt leer. Jeder Aufruf wird nur um eins kleiner: n Ebenen, etwa n² / 2 Vergleiche.', src: 'OPAL LB2 2.2.9b'},
    {d: 3, t: '2.2.9b Quicksort', q: 'Warum braucht die einfache Python-Fassung von Quicksort neben kleiner und groesser auch die Liste `gleich`?', a: ['Sonst käme das Pivot zurück in groesser, und die Rekursion endete nie.', 'Damit das Pivot im Ergebnis doppelt vorkommt und gezählt wird.', 'Damit Quicksort stabil wird und gleiche Werte ihre Reihenfolge behalten.', 'Damit Quicksort keinen zusätzlichen Speicher für Teillisten braucht.'], e: 'Mit nur zwei Listen landet das Pivot selbst wieder in groesser. Der Aufruf wird nicht kleiner – RecursionError.', src: 'OPAL LB2 2.2.9b'},
    {d: 3, t: '2.2.9b Quicksort', q: 'Welche Aussage über Mergesort und Quicksort stimmt?', a: ['Mergesort arbeitet beim Zusammenführen, Quicksort beim Aufteilen', 'Quicksort liegt immer in O(n · log n), Mergesort nur im Mittel.', 'Beide brauchen O(n) Zusatzspeicher, auch Quicksort als in-place-Variante.', 'Quicksort in place ist stabil, Mergesort ist nicht stabil.'], e: 'Mergesort: immer O(n log n), stabil, zusätzlicher Speicher. Quicksort in place: im Mittel O(n log n), schlechtester Fall O(n²), kein zusätzlicher Speicher, nicht stabil.', src: 'OPAL LB2 2.2.9b'},

    // ---------- Backtracking (Lehrplan LB 2, Abiturvorbereitung 2.2) ----------
    {d: 1, t: 'Backtracking', q: 'Nach welchem Muster arbeitet Backtracking?', a: ['prüfen, setzen, Rest rekursiv lösen, bei Misserfolg zurücknehmen', 'teilen, die Hälften rekursiv lösen, die Ergebnisse kombinieren', 'alle Möglichkeiten vollständig erzeugen und erst am Ende prüfen', 'immer das größte noch passende Teil nehmen, ohne zurückzugehen'], e: 'Eine Prüffunktion verhindert ungültige Schritte. Führt ein Weg in eine Sackgasse, wird der letzte Schritt zurückgenommen und der nächste Kandidat probiert.', src: 'OPAL Abi 2.2'},
    {d: 3, t: 'Backtracking', q: 'Ein Plan wird mit Backtracking erstellt. Was passiert, wenn die Zeile `del plan[workshop]` (das Zurücknehmen) fehlt?', a: ['Nach einer Sackgasse bleibt ein Eintrag stehen und blockiert spätere Versuche.', 'Nichts, denn der Eintrag wird beim nächsten Versuch ohnehin überschrieben.', 'Das Programm wird schneller, findet aber denselben Plan wie vorher.', 'Beim Start meldet Python sofort einen SyntaxError wegen der fehlenden Zeile.'], e: 'Überschrieben wird ein Eintrag nur, wenn derselbe Workshop wieder an die Reihe kommt. Bis dahin sieht die Prüffunktion eine Belegung, die gar nicht gilt.', src: 'OPAL Abi 2.2'},

    // ---------- Hash-Suche (Lehrplan LB 2, Abiturvorbereitung 2.3) ----------
    {d: 2, t: 'Hash-Suche', q: 'Mitgliedsnummern werden einmal in ein Dictionary mit der Nummer als Schlüssel übertragen. Was kostet danach eine Prüfung „Ist die Nummer vorhanden?“ im Mittel?', a: ['etwa einen Schritt – O(1)', 'O(log n) wie die binäre Suche', 'O(n) wie die lineare Suche', 'O(n · log n)'], e: 'Die Hash-Suche springt über den Schlüssel direkt an die Stelle. Der Preis ist zusätzlicher Speicher für das Dictionary.', src: 'OPAL Abi 2.3'},
    {d: 3, t: 'Hash-Suche', q: 'n = 4096 = 2¹² Mitglieder, 200 Anmeldungen. Variante B sortiert einmal (n · log₂ n Vergleiche) und sucht dann binär (höchstens 13 Runden). Wie viele Vergleiche braucht B im schlechtesten Fall?', a: ['51 752', '819 200', '49 152', '2 600'], e: '4096 · 12 = 49 152 fürs Sortieren plus 200 · 13 = 2 600 fürs Suchen. Sequenziell (A) wären es 200 · 4096 = 819 200 – etwa 16-mal so viele.', src: 'OPAL Abi 2.3'},

    // ---------- 2.2.10 Berechenbarkeit: technische und theoretische Grenzen ----------
    {d: 1, t: '2.2.10 Berechenbarkeit: technische und theoretische Grenzen', q: 'Woraus ergeben sich technische Grenzen der Berechenbarkeit?', a: ['aus Speicherplatz und Rechenzeit realer Rechner', 'aus Problemen, die prinzipiell kein Algorithmus lösen kann', 'aus Fehlern im Programmcode', 'aus fehlenden Programmiersprachen'], e: 'Ein theoretisch lösbares Problem kann praktisch unlösbar sein, wenn der Aufwand zu stark wächst (z. B. Schach, 16-stellige Passwörter).', src: 'OPAL LB3 2.2.10'},
    {d: 1, t: '2.2.10 Berechenbarkeit: technische und theoretische Grenzen', q: 'Was besagt die Churchsche These?', a: ['Alles intuitiv Berechenbare kann auch eine Turingmaschine berechnen.', 'Jedes Problem lässt sich mit genug Rechenzeit und Speicher lösen.', 'P ist gleich NP, wenn man eine Turingmaschine verwendet.', 'Kein Programm kann für beliebige Programme entscheiden, ob sie anhalten.'], e: 'Sie ist nicht beweisbar, weil „intuitiv berechenbar“ kein mathematisch definierter Begriff ist.', src: 'OPAL LB3 2.2.10'},
    {d: 1, t: '2.2.10 Berechenbarkeit: technische und theoretische Grenzen', q: 'Was ist ein Entscheidungsproblem?', a: ['eine Frage, die für jede Eingabe mit Ja oder Nein beantwortet wird', 'ein Problem, bei dem man zwischen mehreren richtigen Lösungen wählt', 'ein Problem, das sich nicht algorithmisch lösen lässt, also unentscheidbar ist', 'die Suche nach der kürzesten Rundreise durch alle Städte'], e: 'Es heißt entscheidbar, wenn ein Algorithmus für jede Eingabe nach endlich vielen Schritten die richtige Antwort liefert, z. B. „Ist n eine Primzahl?“.', src: 'OPAL LB3 2.2.10'},
    {d: 1, t: '2.2.10 Berechenbarkeit: technische und theoretische Grenzen', q: 'Was bewies Alan Turing über das Halteproblem?', a: ['Kein Algorithmus entscheidet für alle Programme, ob sie anhalten.', 'Es ist lösbar, braucht aber für lange Programme viel Rechenzeit.', 'Es ist nur für Programme mit Schleifen oder Rekursion unlösbar.', 'Mit genug Rechenleistung und Speicher lässt es sich doch immer lösen.'], e: 'Das ist eine theoretische Grenze, unabhängig von der Technik. Wegen der Churchschen These gilt sie für jedes denkbare Verfahren.', src: 'OPAL LB3 2.2.10'},
    {d: 3, t: '2.2.10 Berechenbarkeit: technische und theoretische Grenzen', q: 'Ein Prüfwerkzeug soll für jedes Python-Programm P und jede Eingabe x antworten. Welche Prüfung ist entscheidbar?', a: ['Hält P bei Eingabe x nach höchstens 1 000 000 Rechenschritten an?', 'Hält P bei Eingabe x irgendwann an, wenn man lange genug wartet?', 'Gibt P bei jeder möglichen Eingabe irgendwann den Text „Hallo“ aus?', 'Hält P für alle möglichen Eingaben nach endlich vielen Schritten an?'], e: 'Man lässt P höchstens 1 000 000 Schritte laufen – das endet immer. Die anderen Fragen lassen sich auf das Halteproblem zurückführen.', src: 'OPAL LB3 2.2.10'},
    {d: 1, t: '2.2.10 Berechenbarkeit: technische und theoretische Grenzen', q: 'Was kennzeichnet ein Problem aus NP?', a: ['Eine vorgeschlagene Lösung lässt sich in polynomialer Zeit überprüfen.', 'Es ist nicht berechenbar, weil kein Algorithmus es je lösen kann.', 'Eine Lösung lässt sich in polynomialer Zeit finden, aber nicht überprüfen.', 'NP steht für „nicht polynomial“, es gibt also sicher kein schnelles Verfahren.'], e: 'NP = nichtdeterministisch polynomiell. Ob es für NP-Probleme effiziente Lösungsverfahren gibt (P = NP?), ist ungelöst.', src: 'OPAL LB3 2.2.10'},
    {d: 2, t: '2.2.10 Berechenbarkeit: technische und theoretische Grenzen', q: 'Welche Aussage über P und NP stimmt?', a: ['Jedes Problem aus P liegt auch in NP.', 'Jedes Problem aus NP liegt auch in P – das ist bewiesen.', 'P und NP haben keine gemeinsamen Probleme.', 'NP-Probleme sind unentscheidbar.'], e: 'Was man in polynomialer Zeit lösen kann, kann man auch in polynomialer Zeit prüfen. Die Umkehrung ist die offene Frage P = NP.', src: 'OPAL LB3 2.2.10'},
    {d: 2, t: '2.2.10 Berechenbarkeit: technische und theoretische Grenzen', q: '„Gibt es eine Rundreise durch alle Städte, die kürzer als k km ist?“ Eine Route wird vorgeschlagen. Was lässt sich schnell prüfen?', a: ['ob sie alle Städte besucht und kürzer als k ist, nicht ob sie optimal ist', 'ob sie die kürzeste aller Rundreisen ist, indem man ihre Länge addiert', 'gar nichts, man muss dazu erst alle anderen Routen durchprobieren', 'nur, ob die Zahl der Städte stimmt, aber nicht die Länge der Route'], e: 'Man addiert die n Teilstrecken. Ob es die kürzeste ist, ließe sich nur durch Vergleich mit allen anderen Routen klären.', src: 'OPAL LB3 2.2.10'},
    {d: 2, t: '2.2.10 Berechenbarkeit: technische und theoretische Grenzen', q: 'Paketdienste können die optimale Tour für 60 Stopps nicht mit Brute Force berechnen. Was setzen sie stattdessen ein?', a: ['Heuristiken: schnelle, sehr gute, aber nicht garantiert optimale Routen', 'einen schnelleren Rechner, der trotzdem alle Reihenfolgen durchprobiert', 'die binäre Suche, die die beste Route in log n Schritten findet', 'nichts, denn das Problem ist unentscheidbar und damit nicht lösbar'], e: 'Das Problem des Handlungsreisenden ist entscheidbar, aber mit Brute Force in O(n!) praktisch nicht lösbar.', src: 'OPAL LB2 2.2.4'},
    {d: 3, t: '2.2.10 Berechenbarkeit: technische und theoretische Grenzen', q: 'Ein Programm probiert alle 2ⁿ Auswahlen aus n Standanfragen und schafft 30 Anfragen in einer Stunde. Wie viele schafft ein doppelt so schneller Rechner in einer Stunde?', a: ['31', '60', '32', '45'], e: 'Eine Anfrage mehr verdoppelt die Zahl der Auswahlen: 2 · 2³⁰ = 2³¹. Bei exponentiellem Aufwand hilft bessere Hardware kaum.', src: 'OPAL Abi 2.3'},

    // ---------- AFB I: Grundlagen ----------
    {d: 1, t: '2.2.1 Algorithmen und Komplexität', q: 'Was kann ein Computer beim Sortieren grundsätzlich nur tun?', a: ['zwei Werte vergleichen, Werte vertauschen und Positionen merken', 'die ganze Liste auf einen Blick überschauen und passend ordnen', 'mehrere Werte gleichzeitig vergleichen und sofort einsortieren', 'nur Zahlen vergleichen, aber keine Texte oder Zeichen'], e: 'Mehr als Vergleichen, Vertauschen und Merken von Positionen braucht jedes Sortierverfahren nicht.', src: 'OPAL LB2 2.2.1'},
    {d: 1, t: '2.2.2 Bubblesort', q: 'Was vergleicht Bubblesort in jedem Durchlauf?', a: ['jeweils zwei benachbarte Elemente', 'jedes Element mit dem kleinsten Rest', 'das erste mit dem letzten Element', 'jedes Element mit dem Mittelwert'], e: 'Benachbarte Elemente werden getauscht, wenn sie falsch herum stehen – so steigen die großen Werte nach rechts auf.', src: 'OPAL LB2 2.2.2'},
    {d: 1, t: '2.2.2 Bubblesort', q: 'Wozu braucht man beim Vertauschen zweier Listenelemente die Hilfsvariable `temp`?', a: ['Ohne sie ginge beim ersten Zuweisen ein Wert verloren.', 'Sie macht das Tauschen schneller als ohne Hilfsvariable.', 'Sie zählt mit, wie oft schon getauscht wurde.', 'Sie speichert den Index des größten Elements.'], e: 'temp = a; a = b; b = temp: Der erste Wert wird zwischengespeichert, bevor er überschrieben wird.', src: 'OPAL LB2 2.2.2'},
    {d: 1, t: '2.2.3 Einführung in Komplexität und die O-Notation', q: 'Welchen Fall gibt man bei der O-Notation meist an?', a: ['den schlechtesten Fall (worst case)', 'den besten Fall (best case)', 'den mittleren Fall bei zufälligen Eingaben', 'den Durchschnitt aller Rechner'], e: 'Der schlechteste Fall ist eine Garantie: Mehr Schritte als angegeben braucht der Algorithmus nie.', src: 'OPAL LB2 2.2.3'},
    {d: 1, t: '2.2.4 Komplexitätsklassen im Überblick', q: 'In welcher Klasse liegt der Zugriff auf ein Listenelement über den Index?', a: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], e: 'Der Zugriff über den Index braucht unabhängig von der Länge der Liste immer gleich viele Schritte.', src: 'OPAL LB2 2.2.4'},
    {d: 1, t: '2.2.8 Divide and Conquer, binäre Suche', q: 'In welcher Komplexitätsklasse liegt die binäre Suche?', a: ['O(log n)', 'O(n log n)', 'O(n)', 'O(1)'], e: 'Jeder Vergleich halbiert den Suchbereich, daher höchstens ⌊log₂ n⌋ + 1 Runden.', src: 'OPAL LB2 2.2.8'},
    {d: 1, t: '2.2.5 Insertionsort und Selectionsort', q: 'Was bedeutet „stabil“ bei einem Sortierverfahren?', a: ['Gleiche Schlüssel behalten ihre ursprüngliche Reihenfolge.', 'Das Verfahren braucht für jede Eingabe gleich viele Schritte.', 'Das Verfahren bricht auch bei fehlerhaften Eingaben nie ab.', 'Das Verfahren braucht keinen zusätzlichen Speicher.'], e: 'Stabil sind z. B. Bubblesort, Insertionsort und Mergesort, Selectionsort ist es nicht.', src: 'OPAL LB2 2.2.5'},
    {d: 1, t: '2.2.5 Insertionsort und Selectionsort', q: 'Wie arbeitet Selectionsort?', a: ['Das kleinste unsortierte Element wird nach vorn getauscht.', 'Das erste unsortierte Element wird in den sortierten Teil eingefügt.', 'Benachbarte Elemente werden getauscht, bis nichts mehr zu tauschen ist.', 'Die Liste wird geteilt und die sortierten Hälften zusammengeführt.'], e: 'Sortieren durch Auswählen: In jedem Schritt wird das Minimum des unsortierten Teils gesucht.', src: 'OPAL LB2 2.2.5'},
    {d: 1, t: '2.2.9 Mergesort', q: 'Was geschieht im merge-Schritt von Mergesort?', a: ['Zwei sortierte Listen werden zu einer sortierten Liste vereinigt.', 'Eine Liste wird anhand eines Pivots in kleinere und größere Teile geteilt.', 'Die Liste wird in der Mitte geteilt und beide Hälften werden vertauscht.', 'Aus zwei Listen werden alle doppelten Werte entfernt und sortiert.'], e: 'Es werden immer nur die beiden vorderen Elemente verglichen, das kleinere wandert in die Ergebnisliste.', src: 'OPAL LB2 2.2.9'},
    {d: 1, t: '2.2.4 Komplexitätsklassen im Überblick', q: 'Was ist eine Heuristik?', a: ['ein Näherungsverfahren, das schnell eine gute, nicht sicher beste Lösung liefert', 'ein Verfahren, das nach endlicher Zeit stets die optimale Lösung garantiert und beweist', 'ein Verfahren, das systematisch alle Möglichkeiten vollständig durchprobiert', 'ein Beweis, dass für ein Problem kein Algorithmus existieren kann'], e: 'Heuristiken setzt man ein, wenn eine exakte Lösung (z. B. mit Brute Force) zu aufwendig wäre.', src: 'OPAL LB2 2.2.4'},
    {d: 1, t: '2.2.10 Berechenbarkeit: technische und theoretische Grenzen', q: 'Was kennzeichnet ein Problem aus P?', a: ['Es lässt sich in polynomialer Zeit lösen.', 'Es lässt sich nur in exponentieller Zeit lösen.', 'Es ist nicht entscheidbar.', 'Es lässt sich nur durch Raten lösen.'], e: 'P enthält die Entscheidungsprobleme, die sich in polynomialer Zeit O(nᵏ) lösen lassen.', src: 'OPAL LB3 2.2.10'},
    {d: 1, t: '2.2.10 Berechenbarkeit: technische und theoretische Grenzen', q: 'Was fragt das Halteproblem?', a: ['Hält ein Programm bei einer Eingabe irgendwann an?', 'Wie lange braucht ein gegebenes Programm für diese Eingabe?', 'Ist ein gegebenes Programm frei von Syntax- und Laufzeitfehlern?', 'Liegt ein gegebenes Programm in der Komplexitätsklasse P?'], e: 'Turing hat bewiesen: Es gibt keinen Algorithmus, der das für jedes Programm und jede Eingabe entscheidet.', src: 'OPAL LB3 2.2.10'},
  ]
};
